*{box-sizing:border-box} :root{--bg:#101114;--panel:#17181b;--line:#28292d;--muted:#777a83;--text:#e9e7e2;--gold:#e5b763;--green:#9bbf97;--serif:'Marcellus',Georgia,serif;--sans:'DM Sans',sans-serif;--mono:'DM Mono',monospace} html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:var(--sans)}body{background-image:radial-gradient(ellipse at 50% 0%,#1d1b19 0,transparent 58%)}button{font:inherit;color:inherit}.shell{max-width:1600px;min-height:100vh;margin:auto;padding:0 36px;display:flex;flex-direction:column}.topbar{height:74px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{font-size:14px;letter-spacing:2px;font-weight:800;color:#eee;text-decoration:none;display:flex;align-items:center;gap:10px}.brand-mark{color:var(--gold);font-size:23px}.brand-sub{font-family:var(--mono);font-size:9px;letter-spacing:1.6px;color:#777;margin-left:5px;padding-left:13px;border-left:1px solid #3a3834}.top-meta,.sound-btn{font:10px var(--mono);letter-spacing:1px;color:#9b9ba0;display:flex;align-items:center;gap:9px}.live-dot{height:6px;width:6px;border-radius:50%;background:#90b78a;box-shadow:0 0 9px #88bd79}.divider{height:13px;border-left:1px solid #393a3e;margin:0 3px}.sound-btn{background:none;border:0;cursor:pointer;padding:9px}.sound-btn:hover{color:var(--gold)}.sound-btn span{font-size:9px}.game-layout{display:grid;grid-template-columns:190px minmax(500px,960px) 190px;gap:24px;justify-content:center;align-items:start;padding:36px 0 22px;flex:1}.side-panel{padding-top:7px}.panel-kicker{display:flex;align-items:center;justify-content:space-between;color:#87888d;font:9px var(--mono);letter-spacing:1.2px;margin-bottom:16px}.panel-kicker span{color:#5d5e63}.party-list{display:flex;flex-direction:column;gap:9px}.hero-card{display:flex;align-items:center;gap:10px;padding:9px 8px;border:1px solid #2c2d30;background:linear-gradient(120deg,#1b1c1f,#151619);position:relative;min-height:57px;transition:.2s}.hero-card.active{border-color:#66604e}.hero-avatar{width:34px;height:34px;display:grid;place-items:center;background:#302822;color:#dfb66e;font-size:19px;border:1px solid #53432e}.hero-card:nth-child(2) .hero-avatar{background:#242b28;color:#a8c495;border-color:#39493e}.hero-card:nth-child(3) .hero-avatar{background:#292431;color:#c1a8da;border-color:#45374f}.hero-info{min-width:0;flex:1}.hero-name{font-size:11px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.hero-class{color:#85858b;font:9px var(--mono);margin-top:3px}.hero-hp{margin-top:5px;height:2px;background:#38383a}.hero-hp i{display:block;height:100%;background:#91ab75}.hero-card:nth-child(2) .hero-hp i{background:#98b888}.hero-card:nth-child(3) .hero-hp i{background:#b29acb}.panel-rule{border-top:1px solid var(--line);margin:22px 0 18px}.stat-row{display:flex;align-items:center;justify-content:space-between;margin:13px 0;color:#7e7f84;font:9px var(--mono);letter-spacing:.5px}.stat-row strong{color:#ddd;font:14px var(--mono);font-weight:400}.floor-progress{height:2px;background:#343438;margin:17px 0 10px}.floor-progress div{height:100%;width:0;background:var(--gold);transition:width .5s}.tiny-note{font-size:10px;color:#7b7c80;line-height:1.6;margin:0}.stage-wrap{min-width:0}.stage-heading{display:flex;align-items:flex-end;justify-content:space-between;margin:0 1px 18px}.eyebrow{font:9px var(--mono);letter-spacing:2px;color:var(--gold);margin-bottom:8px}h1{font:31px/1.1 var(--serif);font-weight:400;letter-spacing:.4px;margin:0;color:#ede9e0}h1 em{font-weight:400;color:#c6a873}.floor-badge{border:1px solid #3a3833;min-width:58px;height:53px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;color:#85827a}.floor-badge span{font:8px var(--mono);letter-spacing:1.2px}.floor-badge strong{font:20px var(--serif);color:var(--gold);font-weight:400}.game-frame{width:100%;aspect-ratio:1.6;position:relative;border:1px solid #3d3a33;background:#141516;overflow:hidden;box-shadow:0 14px 50px #0007}canvas{display:block;width:100%;height:100%;image-rendering:auto;cursor:crosshair}.canvas-vignette{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 70px #08090bd9,inset 0 -35px 50px #0e0e10a8}.game-hint{position:absolute;bottom:11px;left:0;right:0;text-align:center;color:#aaa9a1;font:8px var(--mono);letter-spacing:.7px;pointer-events:none;text-shadow:0 1px 3px #000}.keycap{border:1px solid #787268;color:#eee6d4;padding:2px 4px;background:#252421b8;margin:0 4px}.hint-sep{color:var(--gold);margin:0 4px}.toast{position:absolute;top:14px;left:50%;transform:translate(-50%,-8px);opacity:0;padding:8px 13px;background:#161714e8;border:1px solid #554b37;color:#e7d4a9;font:10px var(--mono);letter-spacing:.5px;transition:.25s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.game-overlay{position:absolute;inset:0;display:none;align-items:center;justify-content:center;background:#0d0e10cf;backdrop-filter:blur(4px);z-index:3}.game-overlay.visible{display:flex}.overlay-card{width:min(590px,90%);text-align:center;padding:27px 28px;background:#191a1c;border:1px solid #59503e;box-shadow:0 18px 70px #0009}.overlay-kicker{font:9px var(--mono);color:var(--gold);letter-spacing:2px}.overlay-card h2{font:27px var(--serif);font-weight:400;margin:8px 0 6px}.overlay-copy{font-size:11px;color:#9a9993;line-height:1.55;margin:0 auto 17px;max-width:420px}.choice-list{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.choice{background:#212224;border:1px solid #414044;padding:14px 11px;text-align:left;cursor:pointer;min-height:112px;transition:.18s}.choice:hover{border-color:var(--gold);background:#292723;transform:translateY(-2px)}.choice-icon{font-size:20px;color:var(--gold);display:block;margin-bottom:8px}.choice-title{font-size:11px;font-weight:700;color:#e8e4dc}.choice-desc{font-size:9px;color:#96959a;line-height:1.45;margin-top:5px}.overlay-actions{margin-top:16px}.action-btn{background:#b58d50;color:#171512;border:0;padding:10px 19px;font:10px var(--mono);letter-spacing:1px;cursor:pointer}.action-btn:hover{background:#d3ad70}.bottom-bar{display:flex;justify-content:space-between;align-items:center;padding:12px 2px;color:#85847f;font:9px var(--mono);letter-spacing:.75px}.bottom-bar span:first-child{color:#c3a56e}.bottom-tip{color:#56565b}.footer{height:53px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:#5f6065;font:9px var(--mono);letter-spacing:.8px}.footer button{border:1px solid #393a3e;color:#999;background:transparent;padding:7px 10px;font:9px var(--mono);letter-spacing:.5px;cursor:pointer}.footer button:hover{border-color:#b58d50;color:#e4c384}.controls-list>div{display:flex;align-items:center;gap:4px;margin:12px 0;font:9px var(--mono);color:#b0afb0}.controls-list>div span{width:65px;color:#89898e}.controls-list kbd{font:8px var(--mono);padding:3px 4px;background:#252629;border:1px solid #3d3d40;color:#ddd}.controls-list small{font-size:8px;color:#777}.guide-card{display:flex;gap:10px;margin:0 0 15px}.guide-icon{color:#d8b46f;border:1px solid #4f4532;min-width:29px;height:29px;display:grid;place-items:center;font-size:17px}.guide-icon.violet{color:#bda0d3;border-color:#473951}.guide-icon.gold{color:#e1c277}.guide-card strong{font-size:10px;display:block;margin:1px 0 4px}.guide-card p{font-size:9px;line-height:1.5;color:#85858a;margin:0}.party-coop{display:flex;gap:9px;align-items:flex-start}.coop-symbol{font-size:19px;color:#9bb486}.party-coop p{font-size:9px;color:#89898d;line-height:1.55;margin:0}.party-coop strong{color:#cfcdc6;font-size:10px}.game-frame:after{content:'';position:absolute;inset:0;border:1px solid #ffffff08;pointer-events:none}
@media(max-width:1100px){.shell{padding:0 22px}.game-layout{grid-template-columns:150px minmax(420px,1fr);gap:20px}.right-panel{display:none}}
@media(max-width:700px){.shell{padding:0 12px}.topbar{height:58px}.brand{font-size:12px}.brand-sub{font-size:7px}.top-meta{font-size:8px}.sound-btn span{display:none}.game-layout{display:flex;flex-direction:column;padding:17px 0 10px;gap:12px}.left-panel{order:2;width:100%;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:9px 15px}.left-panel>.panel-kicker:first-child,.party-list{grid-column:1/-1}.party-list{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}.hero-card{padding:5px;gap:5px}.hero-avatar{width:26px;height:26px;font-size:14px}.hero-name{font-size:9px}.hero-class{font-size:7px}.left-panel>.panel-rule{display:none}.left-panel>.panel-kicker:nth-of-type(2){display:none}.stat-row{margin:4px 0}.tiny-note{font-size:9px}.floor-progress{margin:7px 0}.stage-wrap{width:100%;order:1}.stage-heading{margin-bottom:11px}h1{font-size:25px}.game-frame{aspect-ratio:1.18}.bottom-tip{display:none}.bottom-bar{font-size:8px}.footer{height:45px}.choice-list{gap:5px}.choice{padding:9px 7px;min-height:101px}.choice-title{font-size:9px}.choice-desc{font-size:8px}.choice-icon{font-size:17px;margin-bottom:4px}.overlay-card{padding:20px 14px}.overlay-card h2{font-size:22px}.overlay-copy{font-size:10px}.controls-list,.party-coop,.guide-card{display:none}}

(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height,T=32,COLS=30,ROWS=18;
const classes=[
 {name:'Vanguard',role:'IRONCLAD',icon:'♜',color:'#d9a85d',hp:150,damage:18,speed:2.55,range:45,skill:'Aegis pulse',desc:'Briefly shield the whole party.'},
 {name:'Ranger',role:'DEADEYE',icon:'➶',color:'#9fb879',hp:100,damage:14,speed:3.1,range:230,skill:'Piercing shot',desc:'Fire a bolt through every foe.'},
 {name:'Arcanist',role:'SPELLWEAVER',icon:'✦',color:'#b99ada',hp:82,damage:20,speed:2.7,range:210,skill:'Nova burst',desc:'Unleash a blast around you.'},
 {name:'Warden',role:'WILDSHAPER',icon:'❧',color:'#8fc0a1',hp:125,damage:12,speed:2.65,range:135,skill:'Renewal',desc:'Restore the whole party.'},
 {name:'Duelist',role:'QUICKBLADE',icon:'⚔',color:'#d88972',hp:105,damage:22,speed:3.45,range:52,skill:'Shadowstep',desc:'Dash forward, striking foes.'},
 {name:'Cleric',role:'LAMPLIGHTER',icon:'☼',color:'#e4d193',hp:112,damage:13,speed:2.55,range:145,skill:'Sanctuary',desc:'Heal allies and stun nearby foes.'},
 {name:'Riftcaller',role:'VOIDBOUND',icon:'◉',color:'#8fa9d8',hp:92,damage:17,speed:2.85,range:190,skill:'Rift lance',desc:'A devastating long-range lance.'},
 {name:'Berserker',role:'BLOODFURY',icon:'♨',color:'#db7770',hp:132,damage:25,speed:2.85,range:48,skill:'Blood rush',desc:'Gain fury and cleave nearby foes.'}
];
let heroes=[],enemies=[],map=[],floor=1,relics=0,eliteSlain=0,seed=0,toastTimer=0,phase='start',tick=0,exit={x:0,y:0},particles=[],floats=[],keys={},mouse={x:0,y:0},lastTime=0,gameSound=false,audio;
const names=['Mara','Thorn','Vesper'],random=(a,b)=>Math.floor(Math.random()*(b-a+1))+a,dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function showToast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function overlay(html){const el=document.getElementById('game-overlay');el.innerHTML=html;el.classList.add('visible')}
function hideOverlay(){document.getElementById('game-overlay').classList.remove('visible')}
function startScreen(){phase='start';const cards=classes.map((c,i)=>`<button class="choice class-choice" data-class="${i}"><span class="choice-icon" style="color:${c.color}">${c.icon}</span><div class="choice-title">${c.name}</div><div class="choice-desc">${c.role} · ${c.desc}</div></button>`).join('');overlay(`<div class="overlay-card start-card"><div class="overlay-kicker">A THREE-HERO DESCENT</div><h2>Choose your party</h2><p class="overlay-copy">Select three different classes. You can play as the whole party, or share the keyboard with friends.</p><div class="choice-list class-list">${cards}</div><div class="selected-classes" id="selected-classes">Choose 3 heroes to begin · <span>0 / 3</span></div></div>`);const picked=[];document.querySelectorAll('.class-choice').forEach(b=>b.onclick=()=>{const i=+b.dataset.class;if(picked.includes(i))return;if(picked.length>=3){showToast('Your party is already full.');return}picked.push(i);b.classList.add('picked');b.disabled=true;const c=classes[i];document.getElementById('selected-classes').innerHTML=`<span style="color:${c.color}">${picked.map(x=>classes[x].icon+' '+classes[x].name).join('　·　')}</span> <b>${picked.length} / 3</b>`;if(picked.length===3){setTimeout(()=>{heroes=picked.map((ci,id)=>{let c=classes[ci];return{id,name:names[id],classId:ci,class:c,x:0,y:0,hp:c.hp,maxHp:c.hp,damage:c.damage,speed:c.speed,range:c.range,skill:c.skill,skillCd:0,attackCd:0,iframes:0,bonus:0,bonusHp:0,alive:true,color:c.color,dir:0}});beginRun()},280)}})}
function beginRun(){floor=1;relics=0;eliteSlain=0;seed=random(100000,999999);document.getElementById('seed-label').textContent='RUN # '+seed;generateFloor();hideOverlay();phase='play';renderHUD();showToast('The descent begins. Find the stairs.');}
function generateFloor(){map=Array.from({length:ROWS},()=>Array(COLS).fill(1));let rooms=[];for(let tries=0;tries<70&&rooms.length<9;tries++){let w=random(5,9),h=random(4,7),x=random(1,COLS-w-1),y=random(1,ROWS-h-1);if(rooms.every(r=>x>r.x+r.w+1||x+w+1<r.x||y>r.y+r.h+1||y+h+1<r.y)){let r={x,y,w,h,cx:Math.floor(x+w/2),cy:Math.floor(y+h/2)};rooms.push(r);for(let yy=y;yy<y+h;yy++)for(let xx=x;xx<x+w;xx++)map[yy][xx]=0}}
 if(!rooms.length){rooms=[{x:2,y:2,w:COLS-4,h:ROWS-4,cx:COLS>>1,cy:ROWS>>1}];for(let y=2;y<ROWS-2;y++)for(let x=2;x<COLS-2;x++)map[y][x]=0}
 for(let i=1;i<rooms.length;i++){let a=rooms[i-1],b=rooms[i];if(Math.random()<.5){carveH(a.cx,b.cx,a.cy);carveV(a.cy,b.cy,b.cx)}else{carveV(a.cy,b.cy,a.cx);carveH(a.cx,b.cx,b.cy)}}
 const first=rooms[0];heroes.forEach((h,i)=>{h.x=(first.cx+(i-1)*.8)*T+T/2;h.y=first.cy*T+T/2;h.hp=Math.min(h.maxHp,h.hp+Math.ceil(h.maxHp*.18));h.alive=true;h.skillCd=0;h.iframes=0});
 let far=rooms[rooms.length-1];exit={x:far.cx,y:far.cy};if(dist({x:first.cx,y:first.cy},exit)<8){exit={x:COLS-3,y:ROWS-3};map[exit.y][exit.x]=0}
 enemies=[];let count=4+floor*2;for(let n=0;n<count;n++){let p=randomFloorTile(rooms);if(!p)continue;let elite=floor>1&&Math.random()<Math.min(.1+floor*.035,.4);enemies.push({x:p.x*T+T/2,y:p.y*T+T/2,hp:elite?48+floor*11:24+floor*6,maxHp:elite?48+floor*11:24+floor*6,damage:elite?15+floor*2:7+floor,elite,speed:elite?1.03+floor*.025:.72+floor*.025,attackCd:random(0,45),stun:0})}
 particles=[];floats=[];document.getElementById('floor-stat').textContent=String(floor).padStart(2,'0');document.getElementById('floor-badge').textContent=String(floor).padStart(2,'0');document.getElementById('stage-title').innerHTML=floor===1?'The Forgotten<br><em>Underneath</em>':`The ${['Sunken','Hollow','Forgotten','Ashen','Nameless'][floor%5]}<br><em>Depth · ${String(floor).padStart(2,'0')}</em>`;document.getElementById('stage-eyebrow').textContent=floor===1?'A PROCEDURAL DESCENT':'THE DESCENT · FLOOR '+String(floor).padStart(2,'0');document.getElementById('location-label').textContent='◈ '+['THE ENTRY CHAMBER','THE MURMURING HALL','THE DROWNED GALLERY','THE ASHEN VAULT'][floor%4];document.getElementById('threat-stat').textContent=String(enemies.length).padStart(2,'0');document.getElementById('objective-copy').textContent='Clear the floor to find the descent.'}
function carveH(a,b,y){for(let x=Math.min(a,b);x<=Math.max(a,b);x++)map[y][x]=0}function carveV(a,b,x){for(let y=Math.min(a,b);y<=Math.max(a,b);y++)map[y][x]=0}
function randomFloorTile(rooms){for(let t=0;t<100;t++){let r=rooms[random(0,rooms.length-1)],x=random(r.x,r.x+r.w-1),y=random(r.y,r.y+r.h-1);if(map[y]?.[x]===0&&Math.hypot(x-exit.x,y-exit.y)>4&&!heroes.some(h=>Math.hypot(h.x/T-x,h.y/T-y)<4)&&!enemies.some(e=>Math.hypot(e.x/T-x,e.y/T-y)<2))return{x,y}}return null}
function solid(x,y){let tx=Math.floor(x/T),ty=Math.floor(y/T);return tx<0||ty<0||tx>=COLS||ty>=ROWS||map[ty][tx]===1}
function moveBody(o,dx,dy,r=10){if(!solid(o.x+dx-r,o.y-r)&&!solid(o.x+dx+r,o.y+r))o.x+=dx;if(!solid(o.x-r,o.y+dy-r)&&!solid(o.x+r,o.y+dy+r))o.y+=dy}
function aliveHeroes(){return heroes.filter(h=>h.alive)}
function damageEnemy(e,n,x,y){e.hp-=n;floats.push({x:x??e.x,y:y??e.y-10,text:String(n),life:35,color:'#f0c77c'});for(let i=0;i<4;i++)particles.push({x:e.x,y:e.y,vx:(Math.random()-.5)*3,vy:(Math.random()-.5)*3,life:18,color:e.elite?'#d18b63':'#b8a6a0'});if(e.hp<=0){if(e.elite)eliteSlain++;enemies=enemies.filter(a=>a!==e);relics++;document.getElementById('relic-stat').textContent=String(relics).padStart(2,'0');document.getElementById('threat-stat').textContent=String(enemies.length).padStart(2,'0');if(!enemies.length)showToast('The floor is clear. Find the gold-lit descent.')}}
function performAttack(h){if(!h.alive||h.attackCd>0)return;h.attackCd=20;let targets=enemies.filter(e=>dist(h,e)<=h.range+15).sort((a,b)=>dist(h,a)-dist(h,b));if(!targets.length)return;let e=targets[0];damageEnemy(e,h.damage+h.bonus);if(h.range>85){let dx=e.x-h.x,dy=e.y-h.y,d=Math.hypot(dx,dy);particles.push({x:h.x,y:h.y,vx:dx/d*7,vy:dy/d*7,life:13,color:h.color,bolt:true})}}
function partySkill(){let living=aliveHeroes();if(!living.length)return;let h=living.find(a=>a.skillCd<=0);if(!h){showToast('Skills are recharging.');return}h.skillCd=300;let skill=h.skill;
 if(skill==='Aegis pulse'){living.forEach(a=>a.iframes=150);showToast('Aegis pulse — the party is shielded.');}
 else if(skill==='Renewal'||skill==='Sanctuary'){living.forEach(a=>a.hp=Math.min(a.maxHp,a.hp+(skill==='Renewal'?34:25)));if(skill==='Sanctuary')enemies.filter(e=>dist(e,h)<130).forEach(e=>e.stun=90);showToast(skill==='Renewal'?'Renewal — the party is restored.':'Sanctuary — healing light!')}
 else if(skill==='Nova burst'||skill==='Blood rush'){enemies.filter(e=>dist(e,h)<(skill==='Nova burst'?155:105)).slice().forEach(e=>damageEnemy(e,h.damage*2+h.bonus,h.x,h.y-26));if(skill==='Blood rush')h.iframes=45;showToast(skill==='Nova burst'?'Nova burst!':'Blood rush!')}
 else {let target=enemies.filter(e=>dist(e,h)<300).sort((a,b)=>dist(h,a)-dist(h,b))[0];if(skill==='Shadowstep'){let dx=Math.cos(h.dir),dy=Math.sin(h.dir);for(let i=0;i<10;i++)moveBody(h,dx*12,dy*12,10);h.iframes=45;enemies.filter(e=>dist(e,h)<60).slice().forEach(e=>damageEnemy(e,h.damage*2+h.bonus));showToast('Shadowstep!')}else if(target){damageEnemy(target,h.damage*3+h.bonus*2);showToast(skill+'!')}else showToast('No target in range.')}
 renderHUD()}
function damageHero(h,n){if(!h.alive||h.iframes>0)return;h.hp-=n;floats.push({x:h.x,y:h.y-12,text:'-'+n,life:35,color:'#e97870'});if(h.hp<=0){h.hp=0;h.alive=false;showToast(h.name+' has fallen!');}if(!aliveHeroes().length){phase='dead';overlay(`<div class="overlay-card"><div class="overlay-kicker">EXPEDITION ENDED</div><h2>The dungeon claims its own.</h2><p class="overlay-copy">Your party reached floor ${floor}. Every descent leaves a mark.</p><button class="action-btn" id="again-btn">DESCEND AGAIN</button></div>`);document.getElementById('again-btn').onclick=startScreen}renderHUD()}
function update(dt){tick+=dt;let mult=dt/16.67;for(let h of heroes){if(!h.alive)continue;h.attackCd=Math.max(0,h.attackCd-mult);h.skillCd=Math.max(0,h.skillCd-mult);h.iframes=Math.max(0,h.iframes-mult);let dx=0,dy=0,id=h.id;if(id===0){dx=(keys.d?1:0)-(keys.a?1:0);dy=(keys.s?1:0)-(keys.w?1:0)}if(id===1){dx=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0);dy=(keys.ArrowDown?1:0)-(keys.ArrowUp?1:0)}if(id===2){dx=(keys.l?1:0)-(keys.j?1:0);dy=(keys.k?1:0)-(keys.i?1:0)}if(dx||dy){let d=Math.hypot(dx,dy);dx/=d;dy/=d;h.dir=Math.atan2(dy,dx);let speed=h.speed*(keys.space&&id===0||keys.Shift&&id===1||keys.Enter&&id===2?1.9:1);moveBody(h,dx*speed*mult,dy*speed*mult,10)}
 if(enemies.length){let near=enemies.filter(e=>dist(e,h)<=h.range+5).sort((a,b)=>dist(h,a)-dist(h,b))[0];if(near&&h.attackCd<=0)performAttack(h)}}
 for(let e of enemies.slice()){if(e.stun>0){e.stun-=mult;continue}e.attackCd-=mult;let target=aliveHeroes().sort((a,b)=>dist(e,a)-dist(e,b))[0];if(!target)continue;let d=dist(e,target);if(d>19){let dx=(target.x-e.x)/d,dy=(target.y-e.y)/d;let nx=e.x+dx*e.speed*mult,ny=e.y+dy*e.speed*mult;if(!solid(nx, e.y))e.x=nx;if(!solid(e.x,ny))e.y=ny}if(d<25&&e.attackCd<=0){e.attackCd=60;damageHero(target,e.damage)}}
 for(let p of particles){p.x+=p.vx*mult;p.y+=p.vy*mult;p.life-=mult}particles=particles.filter(p=>p.life>0);for(let f of floats){f.y-=.4*mult;f.life-=mult}floats=floats.filter(f=>f.life>0);
 if(phase==='play'&&!enemies.length&&aliveHeroes().some(h=>Math.hypot(h.x-(exit.x*T+T/2),h.y-(exit.y*T+T/2))<28))showRewards()}
function showRewards(){if(phase!=='play')return;phase='reward';let options=makeRewards();overlay(`<div class="overlay-card"><div class="overlay-kicker">FLOOR ${String(floor).padStart(2,'0')} CLEARED</div><h2>A boon for the descent</h2><p class="overlay-copy">Choose one reward for your party. Every find changes the run.</p><div class="choice-list">${options.map((o,i)=>`<button class="choice reward-choice" data-id="${i}"><span class="choice-icon">${o.icon}</span><div class="choice-title">${o.name}</div><div class="choice-desc">${o.desc}</div></button>`).join('')}</div></div>`);document.querySelectorAll('.reward-choice').forEach(b=>b.onclick=()=>{let o=options[+b.dataset.id];o.apply();floor++;generateFloor();phase='play';hideOverlay();renderHUD();showToast(o.name+' claimed. Deeper we go.')})}
function makeRewards(){let pool=[{icon:'✧',name:'Witchglass Charm',desc:'All heroes deal 20% more damage.',apply:()=>heroes.forEach(h=>h.bonus+=Math.ceil(h.damage*.2))},{icon:'♥',name:'Heartwood Locket',desc:'Raise every hero’s max health by 24 and heal them.',apply:()=>heroes.forEach(h=>{h.maxHp+=24;h.hp=Math.min(h.maxHp,h.hp+40)})},{icon:'➶',name:'Swiftstep Greaves',desc:'The whole party moves 12% faster.',apply:()=>heroes.forEach(h=>h.speed*=1.12)},{icon:'⚔',name:'Grave-forged Edge',desc:'A chosen hero gains +9 attack damage.',apply:()=>{let h=heroes[random(0,2)];h.bonus+=9;showToast(h.name+' found the Grave-forged Edge.')}},{icon:'☼',name:'Sunseed Tonic',desc:'Restore 45 health to every hero.',apply:()=>heroes.forEach(h=>h.hp=Math.min(h.maxHp,h.hp+45))},{icon:'◈',name:'Echoing Sigil',desc:'Skills recharge 25% faster.',apply:()=>heroes.forEach(h=>h.skillCd*=.75)},{icon:'⬡',name:'Warden’s Plate',desc:'Increase every hero’s max health by 12.',apply:()=>heroes.forEach(h=>{h.maxHp+=12;h.hp+=12})},{icon:'⌖',name:'Hunter’s Eye',desc:'Deal 10% more damage and extend attack reach.',apply:()=>heroes.forEach(h=>{h.bonus+=Math.ceil(h.damage*.1);h.range+=12})}];let out=[];while(out.length<3){let i=random(0,pool.length-1);if(!out.includes(pool[i]))out.push(pool[i])}return out}

function draw(){ctx.clearRect(0,0,W,H);ctx.fillStyle='#111214';ctx.fillRect(0,0,W,H);for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){let px=x*T,py=y*T;if(map[y][x]===0){ctx.fillStyle=((x*7+y*13)%5===0)?'#292724':'#252422';ctx.fillRect(px,py,T,T);ctx.fillStyle='#ffffff04';ctx.fillRect(px+1,py+1,T-2,1);if((x*11+y*5)%9===0){ctx.fillStyle='#171718';ctx.fillRect(px+randomDet(x,y,11),py+randomDet(y,x,12),2,2)}}else{ctx.fillStyle='#171719';ctx.fillRect(px,py,T,T);ctx.fillStyle='#30302e';ctx.fillRect(px+1,py+2,T-2,T-4);ctx.fillStyle='#3c3a36';ctx.fillRect(px+2,py+2,T-4,2);ctx.fillStyle='#101113';ctx.fillRect(px+2,py+T-3,T-4,2);ctx.fillStyle='#222224';ctx.fillRect(px+3,py+5,2,T-10)}}
 if(exit.x>=0){let ex=exit.x*T+16,ey=exit.y*T+16,unlocked=!enemies.length;ctx.save();ctx.translate(ex,ey);ctx.globalAlpha=.72+.25*Math.sin(tick/240);ctx.fillStyle=unlocked?'#d8ae5b':'#6c5835';ctx.shadowColor=unlocked?'#edc66d':'#d6a64a';ctx.shadowBlur=unlocked?24:8;ctx.beginPath();ctx.ellipse(0,0,13,16,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#131416';ctx.beginPath();ctx.ellipse(0,1,7,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=unlocked?'#eed18a':'#745d37';ctx.beginPath();ctx.arc(0,0,3,0,Math.PI*2);ctx.fill();ctx.restore();if(unlocked){ctx.fillStyle='#e2c17e';ctx.font='9px DM Mono';ctx.textAlign='center';ctx.fillText('DESCEND',ex,ey-23)}}
 for(let e of enemies){ctx.save();ctx.translate(e.x,e.y);ctx.fillStyle='#0009';ctx.beginPath();ctx.ellipse(0,9,e.elite?14:11,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.elite?'#725048':'#4c4546';ctx.beginPath();ctx.arc(0,0,e.elite?11:8,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.elite?'#c98668':'#b3877c';ctx.beginPath();ctx.arc(-3,-2,2,0,Math.PI*2);ctx.arc(3,-2,2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#2a2123';ctx.fillRect(-10,-15,20,3);ctx.fillStyle='#c45d53';ctx.fillRect(-10,-15,20*clamp(e.hp/e.maxHp,0,1),3);if(e.elite){ctx.strokeStyle='#d2a65f';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,0,14,0,Math.PI*2);ctx.stroke()}ctx.restore()}
 for(let h of heroes){if(!h.alive){ctx.globalAlpha=.46}ctx.save();ctx.translate(h.x,h.y);ctx.fillStyle='#0008';ctx.beginPath();ctx.ellipse(0,10,12,5,0,0,Math.PI*2);ctx.fill();ctx.rotate(h.dir);ctx.fillStyle=h.color;ctx.beginPath();ctx.arc(0,0,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ece5d5';ctx.beginPath();ctx.arc(2,-2,2,0,Math.PI*2);ctx.fill();ctx.strokeStyle=h.color;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(2,0);ctx.lineTo(12,0);ctx.stroke();ctx.restore();if(h.iframes>0){ctx.strokeStyle=h.color+'bb';ctx.lineWidth=2;ctx.beginPath();ctx.arc(h.x,h.y,14,0,Math.PI*2);ctx.stroke()}if(!h.alive){ctx.globalAlpha=1}}
 for(let p of particles){ctx.globalAlpha=clamp(p.life/15,0,1);ctx.fillStyle=p.color;if(p.bolt){ctx.strokeStyle=p.color;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x-p.vx*2,p.y-p.vy*2);ctx.stroke()}else{ctx.fillRect(p.x,p.y,3,3)}}ctx.globalAlpha=1;for(let f of floats){ctx.globalAlpha=clamp(f.life/18,0,1);ctx.fillStyle=f.color;ctx.font='bold 11px DM Mono';ctx.textAlign='center';ctx.fillText(f.text,f.x,f.y)}ctx.globalAlpha=1;
 if(phase==='play'&&enemies.length===0){ctx.fillStyle='#e0c58b';ctx.font='10px DM Mono';ctx.textAlign='center';ctx.fillText('THE STAIRS ARE OPEN — FIND THE GOLDEN LIGHT',W/2,24)}if(phase==='start'){ctx.fillStyle='#777';ctx.font='10px DM Mono';ctx.textAlign='center';ctx.fillText('A dungeon is waiting for its heroes.',W/2,H-28)}}
function randomDet(x,y,s){return ((x*13+y*19+s*7)%Math.max(1,T-7))+4}
function renderHUD(){let box=document.getElementById('party-list');box.innerHTML=heroes.map((h,i)=>`<div class="hero-card ${h.alive?'':'fallen'}"><div class="hero-avatar" style="color:${h.color}">${h.class.icon}</div><div class="hero-info"><div class="hero-name">${h.name} ${h.alive?'':'†'}</div><div class="hero-class">${h.class.name.toUpperCase()}</div><div class="hero-hp"><i style="width:${100*h.hp/h.maxHp}%"></i></div></div></div>`).join('');document.getElementById('party-count').textContent=String(aliveHeroes().length).padStart(2,'0')+' / 03';document.getElementById('party-alive').textContent=aliveHeroes().length+' / 3 ALIVE';document.getElementById('floor-stat').textContent=String(floor).padStart(2,'0');document.getElementById('floor-badge').textContent=String(floor).padStart(2,'0');document.getElementById('relic-stat').textContent=String(relics).padStart(2,'0');document.getElementById('elite-stat').textContent=String(eliteSlain).padStart(2,'0');document.getElementById('best-stat').textContent=String(Math.max(floor,+localStorage.getItem('deepBest')||1)).padStart(2,'0');document.getElementById('progress-fill').style.width=(enemies.length?'100%':'0%');document.getElementById('threat-stat').textContent=String(enemies.length).padStart(2,'0')}
function loop(now){let dt=Math.min(40,now-(lastTime||now));lastTime=now;if(phase==='play')update(dt);draw();requestAnimationFrame(loop)}
function pointerPos(ev){let r=canvas.getBoundingClientRect();return{x:(ev.clientX-r.left)*W/r.width,y:(ev.clientY-r.top)*H/r.height}}
canvas.addEventListener('pointerdown',e=>{if(phase!=='play')return;let p=pointerPos(e),h=aliveHeroes()[0];if(!h)return;let worldX=p.x,worldY=p.y;h.dir=Math.atan2(worldY-h.y,worldX-h.x);let target=enemies.filter(a=>dist(a,p)<35).sort((a,b)=>dist(a,p)-dist(b,p))[0];if(target){if(h.attackCd<=0){h.attackCd=20;damageEnemy(target,h.damage+h.bonus)}}else performAttack(h)});
window.addEventListener('keydown',e=>{let k=e.key.length===1?e.key.toLowerCase():e.key;if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();keys[k]=true;if(e.repeat)return;if(k==='q')partySkill();if(k===' '||k==='Shift'||k==='Enter'){let id=k===' '?0:k==='Shift'?1:2,h=heroes[id];if(h?.alive){h.iframes=18;let dx=Math.cos(h.dir),dy=Math.sin(h.dir);for(let n=0;n<5;n++)moveBody(h,dx*7,dy*7,10)}}});window.addEventListener('keyup',e=>{let k=e.key.length===1?e.key.toLowerCase():e.key;keys[k]=false});window.addEventListener('blur',()=>keys={});
document.getElementById('restart-btn').onclick=()=>startScreen();document.getElementById('sound-btn').onclick=()=>{gameSound=!gameSound;document.querySelector('#sound-btn span').textContent=gameSound?'SOUND ON':'SOUND OFF';showToast(gameSound?'Ambient sound enabled.':'Sound off.')};
// Simple procedural ambient soundtrack, only starts after an explicit click.
function soundTick(){if(!gameSound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=[55,65.4,73.4,82.4][Math.floor(Math.random()*4)];g.gain.setValueAtTime(.0001,audio.currentTime);g.gain.exponentialRampToValueAtTime(.015,audio.currentTime+.08);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+1.3);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+1.4)}catch(_){}}
setInterval(soundTick,1250);startScreen();requestAnimationFrame(loop);
})();

