function update(dt){tick+=dt;let mult=dt/16.67;for(let h of heroes){if(!h.alive)continue;h.attackCd=Math.max(0,h.attackCd-mult);h.skillCd=Math.max(0,h.skillCd-mult);h.iframes=Math.max(0,h.iframes-mult);let dx=0,dy=0,id=h.id;if(id===0){dx=(keys.d?1:0)-(keys.a?1:0);dy=(keys.s?1:0)-(keys.w?1:0)}if(id===1){dx=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0);dy=(keys.ArrowDown?1:0)-(keys.ArrowUp?1:0)}if(id===2){dx=(keys.l?1:0)-(keys.j?1:0);dy=(keys.k?1:0)-(keys.i?1:0)}if(dx||dy){let d=Math.hypot(dx,dy);dx/=d;dy/=d;h.dir=Math.atan2(dy,dx);let speed=h.speed*(keys.space&&id===0||keys.Shift&&id===1||keys.Enter&&id===2?1.9:1);moveBody(h,dx*speed*mult,dy*speed*mult,10)}if(enemies.length){let near=enemies.filter(e=>dist(e,h)<=h.range+5).sort((a,b)=>dist(h,a)-dist(h,b))[0];if(near&&h.attackCd<=0)performAttack(h)}}for(let e of enemies.slice()){if(e.stun>0){e.stun-=mult;continue}e.attackCd-=mult;let target=aliveHeroes().sort((a,b)=>dist(e,a)-dist(e,b))[0];if(!target)continue;let d=dist(e,target);if(d>19){let dx=(target.x-e.x)/d,dy=(target.y-e.y)/d,nx=e.x+dx*e.speed*mult,ny=e.y+dy*e.speed*mult;if(!solid(nx,e.y))e.x=nx;if(!solid(e.x,ny))e.y=ny}if(d<25&&e.attackCd<=0){e.attackCd=60;damageHero(target,e.damage)}}for(let p of particles){p.x+=p.vx*mult;p.y+=p.vy*mult;p.life-=mult}particles=particles.filter(p=>p.life>0);for(let f of floats){f.y-=.4*mult;f.life-=mult}floats=floats.filter(f=>f.life>0);if(phase==='play'&&!enemies.length&&aliveHeroes().some(h=>Math.hypot(h.x-(exit.x*T+T/2),h.y-(exit.y*T+T/2))<28))showRewards()}
function showRewards(){if(phase!=='play')return;phase='reward';let options=makeRewards();overlay(`<div class="overlay-card"><div class="overlay-kicker">FLOOR ${String(floor).padStart(2,'0')} CLEARED</div><h2>A boon for the descent</h2><p class="overlay-copy">Choose one reward for your party. Every find changes the run.</p><div class="choice-list">${options.map((o,i)=>`<button class="choice reward-choice" data-id="${i}"><span class="choice-icon">${o.icon}</span><div class="choice-title">${o.name}</div><div class="choice-desc">${o.desc}</div></button>`).join('')}</div></div>`);document.querySelectorAll('.reward-choice').forEach(b=>b.onclick=()=>{let o=options[+b.dataset.id];o.apply();floor++;generateFloor();phase='play';hideOverlay();renderHUD();showToast(o.name+' claimed. Deeper we go.')})}
function makeRewards(){let pool=[{icon:'✧',name:'Witchglass Charm',desc:'All heroes deal 20% more damage.',apply:()=>heroes.forEach(h=>h.bonus+=Math.ceil(h.damage*.2))},{icon:'♥',name:'Heartwood Locket',desc:'Raise every hero’s max health by 24 and heal them.',apply:()=>heroes.forEach(h=>{h.maxHp+=24;h.hp=Math.min(h.maxHp,h.hp+40)})},{icon:'➶',name:'Swiftstep Greaves',desc:'The whole party moves 12% faster.',apply:()=>heroes.forEach(h=>h.speed*=1.12)},{icon:'⚔',name:'Grave-forged Edge',desc:'A chosen hero gains +9 attack damage.',apply:()=>{let h=heroes[random(0,2)];h.bonus+=9;showToast(h.name+' found the Grave-forged Edge.')}},{icon:'☼',name:'Sunseed Tonic',desc:'Restore 45 health to every hero.',apply:()=>heroes.forEach(h=>h.hp=Math.min(h.maxHp,h.hp+45))},{icon:'◈',name:'Echoing Sigil',desc:'Skills recharge 25% faster.',apply:()=>heroes.forEach(h=>h.skillCd*=.75)},{icon:'⬡',name:'Warden’s Plate',desc:'Increase every hero’s max health by 12.',apply:()=>heroes.forEach(h=>{h.maxHp+=12;h.hp+=12})},{icon:'⌖',name:'Hunter’s Eye',desc:'Deal 10% more damage and extend attack reach.',apply:()=>heroes.forEach(h=>{h.bonus+=Math.ceil(h.damage*.1);h.range+=12})}];let out=[];while(out.length<3){let o=pool[random(0,pool.length-1)];if(!out.includes(o))out.push(o)}return out}

