2: 'use strict';
3: const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height,T=32,COLS=30,ROWS=18;
4: const classes=[
5:  {name:'Vanguard',role:'IRONCLAD',icon:'♜',color:'#d9a85d',hp:150,damage:18,speed:2.55,range:45,skill:'Aegis pulse',desc:'Briefly shield the whole party.'},
6:  {name:'Ranger',role:'DEADEYE',icon:'➶',color:'#9fb879',hp:100,damage:14,speed:3.1,range:230,skill:'Piercing shot',desc:'Fire a bolt through every foe.'},
7:  {name:'Arcanist',role:'SPELLWEAVER',icon:'✦',color:'#b99ada',hp:82,damage:20,speed:2.7,range:210,skill:'Nova burst',desc:'Unleash a blast around you.'},
8:  {name:'Warden',role:'WILDSHAPER',icon:'❧',color:'#8fc0a1',hp:125,damage:12,speed:2.65,range:135,skill:'Renewal',desc:'Restore the whole party.'},
9:  {name:'Duelist',role:'QUICKBLADE',icon:'⚔',color:'#d88972',hp:105,damage:22,speed:3.45,range:52,skill:'Shadowstep',desc:'Dash forward, striking foes.'},
10:  {name:'Cleric',role:'LAMPLIGHTER',icon:'☼',color:'#e4d193',hp:112,damage:13,speed:2.55,range:145,skill:'Sanctuary',desc:'Heal allies and stun nearby foes.'},
11:  {name:'Riftcaller',role:'VOIDBOUND',icon:'◉',color:'#8fa9d8',hp:92,damage:17,speed:2.85,range:190,skill:'Rift lance',desc:'A devastating long-range lance.'},
12:  {name:'Berserker',role:'BLOODFURY',icon:'♨',color:'#db7770',hp:132,damage:25,speed:2.85,range:48,skill:'Blood rush',desc:'Gain fury and cleave nearby foes.'}
13: ];
14: let heroes=[],enemies=[],map=[],floor=1,relics=0,eliteSlain=0,seed=0,toastTimer=0,phase='start',tick=0,exit={x:0,y:0},particles=[],floats=[],keys={},lastTime=0,gameSound=false,audio;
15: const names=['Mara','Thorn','Vesper'],random=(a,b)=>Math.floor(Math.random()*(b-a+1))+a,dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
16: function showToast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
17: function overlay(html){const el=document.getElementById('game-overlay');el.innerHTML=html;el.classList.add('visible')}
18: function hideOverlay(){document.getElementById('game-overlay').classList.remove('visible')}
19: function startScreen(){phase='start';const cards=classes.map((c,i)=>`<button class="choice class-choice" data-class="${i}"><span class="choice-icon" style="color:${c.color}">${c.icon}</span><div class="choice-title">${c.name}</div><div class="choice-desc">${c.role} · ${c.desc}</div></button>`).join('');overlay(`<div class="overlay-card start-card"><div class="overlay-kicker">A THREE-HERO DESCENT</div><h2>Choose your party</h2><p class="overlay-copy">Select three different classes. You can play as the whole party, or share the keyboard with friends.</p><div class="choice-list class-list">${cards}</div><div class="selected-classes" id="selected-classes">Choose 3 heroes to begin · <span>0 / 3</span></div></div>`);const picked=[];document.querySelectorAll('.class-choice').forEach(b=>b.onclick=()=>{const i=+b.dataset.class;if(picked.includes(i)||picked.length>=3)return;picked.push(i);b.classList.add('picked');b.disabled=true;const c=classes[i];document.getElementById('selected-classes').innerHTML=`<span style="color:${c.color}">${picked.map(x=>classes[x].icon+' '+classes[x].name).join('　·　')}</span> <b>${picked.length} / 3</b>`;if(picked.length===3)setTimeout(()=>{heroes=picked.map((ci,id)=>{let c=classes[ci];return{id,name:names[id],classId:ci,class:c,x:0,y:0,hp:c.hp,maxHp:c.hp,damage:c.damage,speed:c.speed,range:c.range,skill:c.skill,skillCd:0,attackCd:0,iframes:0,bonus:0,alive:true,color:c.color,dir:0}});beginRun()},280)})}
20: function beginRun(){floor=1;relics=0;eliteSlain=0;seed=random(100000,999999);document.getElementById('seed-label').textContent='RUN # '+seed;generateFloor();hideOverlay();phase='play';renderHUD();showToast('The descent begins. Find the stairs.')}
21: function generateFloor(){map=Array.from({length:ROWS},()=>Array(COLS).fill(1));let rooms=[];for(let tries=0;tries<70&&rooms.length<9;tries++){let w=random(5,9),h=random(4,7),x=random(1,COLS-w-1),y=random(1,ROWS-h-1);if(rooms.every(r=>x>r.x+r.w+1||x+w+1<r.x||y>r.y+r.h+1||y+h+1<r.y)){let r={x,y,w,h,cx:Math.floor(x+w/2),cy:Math.floor(y+h/2)};rooms.push(r);for(let yy=y;yy<y+h;yy++)for(let xx=x;xx<x+w;xx++)map[yy][xx]=0}}
22:  if(!rooms.length){rooms=[{x:2,y:2,w:COLS-4,h:ROWS-4,cx:COLS>>1,cy:ROWS>>1}];for(let y=2;y<ROWS-2;y++)for(let x=2;x<COLS-2;x++)map[y][x]=0}
23:  for(let i=1;i<rooms.length;i++){let a=rooms[i-1],b=rooms[i];if(Math.random()<.5){carveH(a.cx,b.cx,a.cy);carveV(a.cy,b.cy,b.cx)}else{carveV(a.cy,b.cy,a.cx);carveH(a.cx,b.cx,b.cy)}}
24:  const first=rooms[0];heroes.forEach((h,i)=>{h.x=(first.cx+(i-1)*.8)*T+T/2;h.y=first.cy*T+T/2;h.hp=Math.min(h.maxHp,h.hp+Math.ceil(h.maxHp*.18));h.alive=true;h.skillCd=0;h.iframes=0});let far=rooms[rooms.length-1];exit={x:far.cx,y:far.cy};if(Math.hypot(first.cx-exit.x,first.cy-exit.y)<8){exit={x:COLS-3,y:ROWS-3};map[exit.y][exit.x]=0}
25:  enemies=[];for(let n=0;n<4+floor*2;n++){let p=randomFloorTile(rooms);if(!p)continue;let elite=floor>1&&Math.random()<Math.min(.1+floor*.035,.4),hp=elite?48+floor*11:24+floor*6;enemies.push({x:p.x*T+T/2,y:p.y*T+T/2,hp,maxHp:hp,damage:elite?15+floor*2:7+floor,elite,speed:elite?1.03+floor*.025:.72+floor*.025,attackCd:random(0,45),stun:0})}
26:  document.getElementById('floor-stat').textContent=String(floor).padStart(2,'0');document.getElementById('floor-badge').textContent=String(floor).padStart(2,'0');document.getElementById('stage-title').innerHTML=floor===1?'The Forgotten<br><em>Underneath</em>':`The ${['Sunken','Hollow','Forgotten','Ashen','Nameless'][floor%5]}<br><em>Depth · ${String(floor).padStart(2,'0')}</em>`;document.getElementById('stage-eyebrow').textContent=floor===1?'A PROCEDURAL DESCENT':'THE DESCENT · FLOOR '+String(floor).padStart(2,'0');document.getElementById('location-label').textContent='◈ '+['THE ENTRY CHAMBER','THE MURMURING HALL','THE DROWNED GALLERY','THE ASHEN VAULT'][floor%4];document.getElementById('threat-stat').textContent=String(enemies.length).padStart(2,'0');document.getElementById('objective-copy').textContent='Clear the floor to find the descent.'}
27: function carveH(a,b,y){for(let x=Math.min(a,b);x<=Math.max(a,b);x++)map[y][x]=0}function carveV(a,b,x){for(let y=Math.min(a,b);y<=Math.max(a,b);y++)map[y][x]=0}
28: function randomFloorTile(rooms){for(let t=0;t<100;t++){let r=rooms[random(0,rooms.length-1)],x=random(r.x,r.x+r.w-1),y=random(r.y,r.y+r.h-1);if(map[y]?.[x]===0&&Math.hypot(x-exit.x,y-exit.y)>4&&!heroes.some(h=>Math.hypot(h.x/T-x,h.y/T-y)<4)&&!enemies.some(e=>Math.hypot(e.x/T-x,e.y/T-y)<2))return{x,y}}return null}
29: function solid(x,y){let tx=Math.floor(x/T),ty=Math.floor(y/T);return tx<0||ty<0||tx>=COLS||ty>=ROWS||map[ty][tx]===1}
30: function moveBody(o,dx,dy,r=10){if(!solid(o.x+dx-r,o.y-r)&&!solid(o.x+dx+r,o.y+r))o.x+=dx;if(!solid(o.x-r,o.y+dy-r)&&!solid(o.x+r,o.y+dy+r))o.y+=dy}
31: function aliveHeroes(){return heroes.filter(h=>h.alive)}
32: function damageEnemy(e,n,x,y){e.hp-=n;floats.push({x:x??e.x,y:y??e.y-10,text:String(n),life:35,color:'#f0c77c'});for(let i=0;i<4;i++)particles.push({x:e.x,y:e.y,vx:(Math.random()-.5)*3,vy:(Math.random()-.5)*3,life:18,color:e.elite?'#d18b63':'#b8a6a0'});if(e.hp<=0){if(e.elite)eliteSlain++;enemies=enemies.filter(a=>a!==e);relics++;document.getElementById('relic-stat').textContent=String(relics).padStart(2,'0');document.getElementById('threat-stat').textContent=String(enemies.length).padStart(2,'0');if(!enemies.length)showToast('The floor is clear. Find the gold-lit descent.')}}
33: function performAttack(h){if(!h.alive||h.attackCd>0)return;h.attackCd=20;let targets=enemies.filter(e=>dist(h,e)<=h.range+15).sort((a,b)=>dist(h,a)-dist(h,b));if(!targets.length)return;let e=targets[0];damageEnemy(e,h.damage+h.bonus);if(h.range>85){let dx=e.x-h.x,dy=e.y-h.y,d=Math.hypot(dx,dy);particles.push({x:h.x,y:h.y,vx:dx/d*7,vy:dy/d*7,life:13,color:h.color,bolt:true})}}
